import threading
class TotalWorker(threading.Thread):
    def __init__(self, values):
        super().__init__()
        self.values = values
        self.result = None
    def run(self): self.result = sum(self.values)
def solve(data):
    workers = [TotalWorker(data['left']), TotalWorker(data['right'])]
    for worker in workers: worker.start()
    for worker in workers: worker.join()
    return [worker.result for worker in workers]
